pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newLimit, uint256 wagerValue) internal {
        wagerValue = bound(wagerValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= wagerValue);
        try c.AdjustBetAmounts(newLimit) {} catch { return; }
        uint256 lim;
        try c.currentBetLimit() returns (uint256 __r) { lim = __r; } catch { return; }
        bool reverted;
        try c.wager{value: wagerValue}() { reverted = false; } catch { reverted = true; }
        bool wagered;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wagered = __r; } catch { return; }
        assertTrue(reverted && lim == newLimit && !wagered);
    }

    function testFuzz_run(uint256 newLimit, uint256 wagerValue) public {
        _run(newLimit, wagerValue);
    }

    receive() external payable {}
}
